// ============================================================
//  خواندن ایمن session
// ============================================================
function hasPendingOrderInSession() {
  try {
    return !!sessionStorage.getItem(SESSION_KEYS.PENDING_ORDER);
  } catch {
    return false;
  }
}

function hasPendingCartInSession() {
  try {
    const raw = sessionStorage.getItem(SESSION_KEYS.PENDING_CART);
    if (!raw) return false;
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed?.orders) && parsed.orders.length > 0;
  } catch {
    return false;
  }
}

function getPendingCartCount() {
  try {
    const raw = sessionStorage.getItem(SESSION_KEYS.PENDING_CART);
    if (!raw) return 0;
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed?.orders) ? parsed.orders.length : 0;
  } catch {
    return 0;
  }
}

// ============================================================
//  استخراج سگ pending (تک سفارش)
//  ✅ FIX: lifestyle fields خوانده می‌شوند
// ============================================================
function getPendingDogsFromSession() {
  try {
    const raw = sessionStorage.getItem(SESSION_KEYS.PENDING_DOG);
    if (raw) {
      const dog = JSON.parse(raw);
      if (dog && (dog.dog_name || dog.name)) {
        return [{
          dog_name: dog.dog_name || dog.name,
          name: dog.dog_name || dog.name,
          weight_kg: dog.weight_kg,
          age_months: dog.age_months,
          breed: dog.breed || 'medium',
          is_neutered: !!dog.is_neutered,
          bcs: dog.bcs || 'ideal',
          disease: dog.disease || 'healthy',
          allergens: Array.isArray(dog.allergens) ? dog.allergens : [],
          // ✅ lifestyle fields
          activity: dog.activity || 'moderate',
          pregnancy: dog.pregnancy || 'no',
          surgery: dog.surgery || 'no_surgery',
          temperature: dog.temperature || 'moderate',
          stress: dog.stress || 'low',
        }];
      }
    }

    const fallback = sessionStorage.getItem(SESSION_KEYS.QUICK_FORM);
    if (!fallback) return [];
    const form = JSON.parse(fallback);
    if (!form || !form.dog_name) return [];
    return [{
      dog_name: form.dog_name,
      name: form.dog_name,
      weight_kg: form.weight_kg,
      age_months: form.age_months,
      breed: form.breed || 'medium',
      is_neutered: !!form.is_neutered,
      bcs: form.bcs || 'ideal',
      disease: form.disease || 'healthy',
      allergens: Array.isArray(form.allergens) ? form.allergens : [],
      // ✅ lifestyle fields
      activity: form.activity || 'moderate',
      pregnancy: form.pregnancy || 'no',
      surgery: form.surgery || 'no_surgery',
      temperature: form.temperature || 'moderate',
      stress: form.stress || 'low',
    }];
  } catch {
    return [];
  }
}

// ============================================================
//  ساخت سگ‌های pending (تک سفارش)
//  ✅ FIX: lifestyle fields ارسال می‌شوند
// ============================================================
async function createPendingDogsIfAny() {
  const pendingDogs = getPendingDogsFromSession();
  if (pendingDogs.length === 0) {
    return { createdCount: 0, failedCount: 0, lastDogId: null, lastError: null };
  }

  let createdCount = 0;
  let failedCount = 0;
  let lastDogId = null;
  let lastError = null;

  for (const dog of pendingDogs) {
    try {
      const res = await userAxios.post('/api/dogs', {
        name: dog.dog_name || dog.name,
        breed: dog.breed || 'medium',
        weight_kg: Number(dog.weight_kg) || 0,
        age_months: Number(dog.age_months) || 0,
        is_neutered: !!dog.is_neutered,
        bcs: dog.bcs || 'ideal',
        disease: dog.disease || 'healthy',
        allergens: Array.isArray(dog.allergens) ? dog.allergens : [],
        // ✅ lifestyle fields
        activity: dog.activity || 'moderate',
        pregnancy: dog.pregnancy || 'no',
        surgery: dog.surgery || 'no_surgery',
        temperature: dog.temperature || 'moderate',
        stress: dog.stress || 'low',
      });

      if (res?.data?.dog?.id) {
        lastDogId = res.data.dog.id;
        createdCount += 1;
      } else {
        failedCount += 1;
        lastError = res?.data?.detail || 'پاسخ سرور ناقص است (شناسهٔ سگ دریافت نشد)';
        console.warn('سگ pending ساخته نشد (پاسخ ناقص):', lastError);
      }
    } catch (err) {
      failedCount += 1;
      lastError = err?.response?.data?.detail || err?.message || 'خطای نامشخص';
      console.warn('سگ pending ساخته نشد:', lastError);
    }
  }

  return { createdCount, failedCount, lastDogId, lastError };
}

// ============================================================
//  Helperهای پاک‌سازی
// ============================================================
function clearPendingDogMarker() {
  try {
    sessionStorage.removeItem(SESSION_KEYS.PENDING_DOG);
  } catch { /* silent */ }
}

function clearAllPendingSessions() {
  try {
    sessionStorage.removeItem(SESSION_KEYS.PENDING_ORDER);
    sessionStorage.removeItem(SESSION_KEYS.PENDING_DOG);
    sessionStorage.removeItem(SESSION_KEYS.QUICK_FORM);
    sessionStorage.removeItem(SESSION_KEYS.QUICK_RESULT);
    sessionStorage.removeItem(SESSION_KEYS.PENDING_CART);
  } catch { /* silent */ }
}

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function UserLogin() {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { toast, showToast, hideToast } = useToast();

  const next = searchParams.get('next') || 'panel';

  const hasPendingOrder = useMemo(() => hasPendingOrderInSession(), []);
  const hasPendingCart = useMemo(() => hasPendingCartInSession(), []);
  const pendingCartCount = useMemo(() => getPendingCartCount(), []);

  const pendingDogs = useMemo(() => getPendingDogsFromSession(), []);
  const hasPendingDog = pendingDogs.length > 0;

  // ============================================================
  //  ✅ FIX v7: هدایت به صفحه سبد — مهمان بعد از لاگین
  //  دیگه سبد رو اینجا submit نمی‌کنیم. سبد خرید در localStorage
  //  ذخیره شده و در طول فرآیند لاگین حفظ می‌شه. کاربر باید خودش
  //  در /cart روی «ادامه و انتخاب آدرس» بزنه و آدرس تحویل رو وارد
  //  کنه. این منطقاً درست‌تره چون:
  //    ۱. آدرس فقط از کاربر لاگین‌شده گرفته می‌شه
  //    ۲. کاربر می‌تونه قبل از submit، آدرس رو بررسی/ویرایش کنه
  //    ۳. سگ‌ها در backend به‌صورت خودکار از داده‌های سفارش ساخته
  //       می‌شن (_create_dog_from_order در user_routes.py)
  // ============================================================
  const finishPendingCart = async () => {
    // فقط marker رو پاک می‌کنیم — سبد در localStorage هست
    try {
      sessionStorage.removeItem(SESSION_KEYS.PENDING_CART);
    } catch { /* silent */ }

    showToast(
      'success',
      'خوش برگشتی! سفارش‌های شما در سبد آماده‌ی تکمیل است.',
      { duration: TOAST_DURATION }
    );

    return {
      navigatedTo: '/panel/cart?from=login',
      delay: TOAST_VISIBLE_MS,
    };
  };

  // ============================================================
  //  📦 ثبت سفارش تک — فقط برای 401-recovery
  //  (این مسیر فقط وقتی اجرا می‌شه که توکن در حین submit یک سفارش
  //   تک منقضی شده باشه و سفارش از قبل delivery داشته باشه)
  // ============================================================
  const finishPendingOrder = async () => {
    const raw = sessionStorage.getItem(SESSION_KEYS.PENDING_ORDER);

    let createdDogsCount = 0;
    let failedDogsCount = 0;
    let lastDogId = null;
    let dogErrorMsg = null;

    try {
      const result = await createPendingDogsIfAny();
      createdDogsCount = result.createdCount;
      failedDogsCount = result.failedCount;
      lastDogId = result.lastDogId;
      dogErrorMsg = result.lastError;
    } catch (err) {
      console.warn('خطا در ساخت سگ‌های pending:', err);
      failedDogsCount += 1;
      dogErrorMsg = err?.message;
    }

    clearPendingDogMarker();

    if (failedDogsCount > 0) {
      showToast(
        'error',
        `برخی سگ‌ها اضافه نشدند (${failedDogsCount} مورد): ${dogErrorMsg || 'خطای نامشخص'}`,
        { duration: 5000 }
      );
    }

    if (!raw) {
      if (createdDogsCount > 0) {
        showToast('success', `🎉 خوش آمدی! ${createdDogsCount} سگ به «سگ‌های من» اضافه شد`, { duration: TOAST_DURATION });
      }
      return { navigatedTo: '/panel', delay: TOAST_VISIBLE_MS };
    }

    try {
      const formValues = JSON.parse(raw);

      let dogId = formValues.dog_id || lastDogId || null;
      if (!dogId && formValues.dog_name) {
        try {
          const dogsRes = await userAxios.get('/api/dogs');
          const dogsList = Array.isArray(dogsRes.data) ? dogsRes.data : [];
          const matchingDog = dogsList.find((d) => d.name === formValues.dog_name);
          if (matchingDog?.id) dogId = matchingDog.id;
        } catch { /* Non-critical */ }
      }

      const payload = {
        ...formValues,
        ...(dogId ? { dog_id: dogId } : {}),
        allergens: Array.isArray(formValues.allergens) ? formValues.allergens : [],
      };

      const res = await userAxios.post('/api/submit-order', payload);

      if (!res?.data?.order_id) {
        throw new Error('پاسخ سرور ناقص است (شمارهٔ سفارش دریافت نشد)');
      }

      clearAllPendingSessions();

      const dogMsg = createdDogsCount > 0 ? ` و ${createdDogsCount} سگ اضافه شد` : '';
      showToast(
        'success',
        `✅ سفارش #${res.data.order_id} با موفقیت ثبت شد${dogMsg}`,
        { duration: TOAST_DURATION }
      );

      return {
        navigatedTo: `/panel/orders/${res.data.order_id}`,
        delay: TOAST_VISIBLE_MS,
      };
    } catch (err) {
      const errorMsg = err.response?.data?.detail || err.message || 'خطای نامشخص';

      showToast(
        'error',
        'ورود موفق بود، اما ثبت سفارش با خطا مواجه شد: ' +
          errorMsg +
          ' — اطلاعات سفارش شما حفظ شده و می‌توانید از صفحهٔ اصلی دوباره تلاش کنید.',
        { duration: 4500 }
      );

      return { navigatedTo: '/', delay: TOAST_ERROR_DELAY };
    }
  };

  // ============================================================
  //  🛒 انتقال سفارش تک به سبد خرید
  // ============================================================
  const movePendingOrderToCart = async () => {
    let formValues;
    try {
      const raw = sessionStorage.getItem(SESSION_KEYS.PENDING_ORDER);
      if (!raw) {
        return { navigatedTo: '/panel', delay: TOAST_VISIBLE_MS };
      }
      formValues = JSON.parse(raw);
    } catch {
      return { navigatedTo: '/panel', delay: TOAST_VISIBLE_MS };
    }

    if (!formValues || typeof formValues !== 'object') {
      return { navigatedTo: '/panel', delay: TOAST_VISIBLE_MS };
    }

    const hasDelivery =
      formValues.delivery_lat != null &&
      formValues.delivery_lng != null &&
      formValues.delivery_address;

    const handleCartMoveFailure = async (reason) => {
      if (hasDelivery) {
        showToast(
          'error',
          `${reason} سفارش مستقیماً ثبت می‌شود.`,
          { duration: 4000 }
        );
        return await finishPendingOrder();
      }
      showToast(
        'error',
        `${reason} — لطفاً از صفحه اصلی دوباره تلاش کنید.`,
        { duration: 5000 }
      );
      clearAllPendingSessions();
      return { navigatedTo: '/', delay: TOAST_VISIBLE_MS };
    };

    let lastDogId = null;
    try {
      const result = await createPendingDogsIfAny();
      lastDogId = result.lastDogId;
      if (result.failedCount > 0) {
        showToast(
          'error',
          `برخی سگ‌ها اضافه نشدند (${result.failedCount} مورد): ${result.lastError || 'خطای نامشخص'}`,
          { duration: 5000 }
        );
      }
    } catch (err) {
      console.warn('خطا در ساخت سگ‌های pending:', err);
    }

    clearPendingDogMarker();

    let dogId = formValues.dog_id || lastDogId || null;
    if (!dogId && formValues.dog_name) {
      try {
        const dogsRes = await userAxios.get('/api/dogs');
        const dogsList = Array.isArray(dogsRes.data) ? dogsRes.data : [];
        const matchingDog = dogsList.find((d) => d.name === formValues.dog_name);
        if (matchingDog?.id) dogId = matchingDog.id;
      } catch {
        /* Non-critical */
      }
    }

    if (!dogId) {
      return await handleCartMoveFailure('امکان افزودن سگ به سبد نبود.');
    }

    let summary = {};
    try {
      const rawResult = sessionStorage.getItem(SESSION_KEYS.QUICK_RESULT);
      if (rawResult) summary = JSON.parse(rawResult) || {};
    } catch {
      /* ignore */
    }

    const hasPricing =
      summary?.pricing?.total_order_price ||
      summary?.order_total?.total_price_toman;

    if (!hasPricing) {
      const fs = formValues;
      const formTotal =
        Number(fs.total_price) ||
        Number(fs.total_order_price) ||
        Number(fs.total_price_toman) ||
        0;

      if (formTotal > 0) {
        summary = {
          ...summary,
          pricing: {
            ...(summary?.pricing || {}),
            total_order_price: formTotal,
            final_price_daily:
              Number(fs.daily_price) ||
              Number(fs.final_price_daily) ||
              0,
          },
          order_total: {
            ...(summary?.order_total || {}),
            total_price_toman: formTotal,
            days: Number(fs.days_count) || 7,
            total_weight_kg: Number(fs.total_weight_kg) || 0,
          },
          weight_kg: Number(fs.weight_kg) || 0,
        };
      }
    }

    const orderForCart = {
      form: { ...formValues, dog_id: dogId },
      summary,
    };

    const result = addPendingOrderToCart(orderForCart);

    if (!result.ok) {
      if (result.reason === 'duplicate') {
        clearAllPendingSessions();
        showToast(
          'success',
          'این سفارش قبلاً به سبد اضافه شده بود. به سبد منتقل می‌شوید...',
          { duration: TOAST_DURATION }
        );
        return {
          navigatedTo: '/panel/cart?from=login',
          delay: TOAST_VISIBLE_MS,
        };
      }

      const reasonText =
        result.reason === 'limit'
          ? `سبد پر است (حداکثر ${result.max} سفارش).`
          : 'خطا در افزودن به سبد.';
      return await handleCartMoveFailure(reasonText);
    }

    clearAllPendingSessions();
    showToast(
      'success',
      'سفارش شما به سبد خرید اضافه شد. آدرس را در مرحله پرداخت وارد کنید.',
      { duration: TOAST_DURATION }
    );
    return {
      navigatedTo: '/panel/cart?from=login',
      delay: TOAST_VISIBLE_MS,
    };
  };

  // ============================================================
  //  🚦 مسیر بعد از login موفق
  //  ✅ FIX: استفاده از next param در نبودِ pending
  // ============================================================
  const handlePostLoginActions = async () => {
    if (hasPendingCartInSession()) {
      return await finishPendingCart();
    }

    if (hasPendingOrderInSession()) {
      return await movePendingOrderToCart();
    }

    if (getPendingDogsFromSession().length > 0) {
      try {
        const { createdCount, failedCount, lastError } = await createPendingDogsIfAny();

        clearPendingDogMarker();

        if (createdCount > 0) {
          showToast('success', `🎉 ${createdCount} سگ به «سگ‌های من» اضافه شد`, { duration: TOAST_DURATION });
        }
        if (failedCount > 0) {
          showToast(
            'error',
            `برخی سگ‌ها اضافه نشدند (${failedCount} مورد): ${lastError || 'خطای نامشخص'}`,
            { duration: 5000 }
          );
        }
      } catch (err) {
        console.warn('خطا در ساخت سگ‌های pending:', err);
      }
    }

    // ✅ FIX: استفاده از next در نبودِ pending
    let fallbackDestination = '/panel';
    if (next === 'cart') fallbackDestination = '/panel/cart';
    else if (next === 'order') fallbackDestination = '/panel/orders';

    return { navigatedTo: fallbackDestination, delay: TOAST_VISIBLE_MS };
  };

  // ============================================================
  //  🚀 Submit
  // ============================================================
  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!username.trim() || !password) {
      setError('لطفاً نام کاربری و رمز عبور را وارد کنید');
      return;
    }

    setLoading(true);
    setError('');

    let destination = null;
    let loginSucceeded = false;

    try {
      const res = await userAxios.post('/api/auth/login', {
        username: username.trim(),
        password,
      });

      if (res?.data?.success) {
        if (!res.data.token) {
          setError('پاسخ سرور ناقص است (توکن دریافت نشد). لطفاً با پشتیبانی تماس بگیرید.');
          return;
        }

        localStorage.setItem(STORAGE_KEYS.USER_TOKEN, res.data.token);
        localStorage.setItem(STORAGE_KEYS.USER_DATA, JSON.stringify(res.data.user || {}));

        window.dispatchEvent(new Event(AUTH_EVENT));
        window.dispatchEvent(new Event(USER_DATA_EVENT));

        loginSucceeded = true;

        destination = await handlePostLoginActions();
      } else {
        setError(
          res?.data?.detail ||
            res?.data?.message ||
            'نام کاربری یا رمز عبور اشتباه است.'
        );
      }
    } catch (err) {
      const detail =
        err.response?.data?.detail ||
        err.response?.data?.message ||
        (typeof err.response?.data === 'string' ? err.response.data : null) ||
        'نام کاربری یا رمز عبور اشتباه است';
      setError(detail);
    } finally {
      if (!loginSucceeded) {
        setLoading(false);
      }
    }

    if (destination) {
      setTimeout(
        () => navigate(destination.navigatedTo, { replace: true }),
        destination.delay
      );
    }
  };

  const registerUrl = `/register${
    hasPendingCart ? '?next=cart' : hasPendingOrder ? '?next=order' : ''
  }`;
  const canSubmit = !!(!loading && username.trim() && password);

  const inputBase =
    'w-full h-12 px-4 border rounded-xl text-sm bg-white dark:bg-ink-900 text-ink-900 dark:text-cream-100 placeholder-ink-400 dark:placeholder-cream-500 focus:ring-4 focus:outline-none transition-all duration-200 border-ink-200 dark:border-dark-600 focus:border-brand-500 focus:ring-brand-500/10';

  return (
    <div
      className="min-h-screen min-h-[100dvh] flex bg-paper-100 dark:bg-ink-900 safe-top safe-bottom font-body"
      dir="rtl"
    >
      {toast && (
        <div className="fixed inset-x-0 top-0 z-[100] pointer-events-none flex justify-center px-4 pt-4 safe-top">
          <div className="pointer-events-auto w-full max-w-md">
            <ToastView {...toast} onClose={hideToast} />
          </div>
        </div>
      )}

      {/* Brand Panel */}
      <aside className="hidden lg:flex lg:w-1/2 xl:w-[45%] bg-ink-900 text-cream-100 relative overflow-hidden border-l border-ink-800">
        <div className="absolute inset-0 z-0">
          <SiteImage
            imageKey="login_side_image"
            showPlaceholder={true}
            placeholderContent={null}
            className="w-full h-full object-cover opacity-20"
          />
        </div>
        <div className="absolute top-0 right-0 w-[40rem] h-[40rem] bg-brand-500/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/3 z-0" />
        <div className="absolute bottom-0 left-0 w-[30rem] h-[30rem] bg-accent-500/10 rounded-full blur-3xl translate-y-1/3 -translate-x-1/4 z-0" />

        <div className="relative z-10 flex flex-col justify-start pt-20 px-12 xl:px-20 w-full h-full">
          <Link to="/" className="flex items-center gap-3 group w-fit mb-16">
            <div className="w-12 h-12 rounded-2xl bg-brand-500 flex items-center justify-center shadow-brand group-hover:scale-105 transition-transform">
              <SiteImage
                imageKey="icon_paw"
                showPlaceholder={true}
                placeholderContent={<span className="text-2xl">🐾</span>}
                className="w-7 h-7 object-contain"
              />
            </div>
            <div>
              <div className="font-miko text-xl">میکو</div>
              <div className="text-[11px] text-brand-300 font-bold mt-0.5">غذای سالم و علمی</div>
            </div>
          </Link>

          <div className="max-w-md">
            <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-full bg-white/5 border border-white/10 text-xs font-bold mb-6 text-brand-200">
              <span className="w-1.5 h-1.5 rounded-full bg-brand-400 animate-pulse" />
              <span>خوش برگشتی!</span>
            </div>
            <h1 className="font-display text-3xl sm:text-4xl lg:text-5xl font-black leading-[1.2] tracking-tight mb-6">
              منتظرت
              <br />
              <span className="text-brand-400">بودیم.</span>
            </h1>
            <p className="text-sm xl:text-base text-cream-300/80 leading-relaxed mb-12">
              وارد حساب کاربری خود شوید تا سفارش‌ها، سگ‌ها و رژیم‌های اختصاصی خود را مدیریت کنید.
            </p>
            <div className="grid grid-cols-2 gap-3">
              {LOGIN_BENEFITS.map((b, i) => (
                <div
                  key={i}
                  className="bg-white/5 backdrop-blur-md rounded-2xl p-4 border border-white/10 hover:bg-white/10 transition-colors duration-300"
                >
                  <div className="text-brand-400 mb-3">{b.icon}</div>
                  <div className="text-sm font-bold text-cream-100 mb-1">{b.title}</div>
                  <div className="text-[11px] text-cream-400 leading-relaxed">{b.desc}</div>
                </div>
              ))}
            </div>
          </div>

          <div className="mt-auto pb-8 text-[11px] text-cream-500">
            © ۱۴۰۴ سیستم تغذیه اختصاصی سگ (میکو) — تمام حقوق محفوظ است
          </div>
        </div>
      </aside>

      {/* Form Panel */}
      <main className="flex-1 flex items-center justify-center p-4 sm:p-6 lg:p-10 relative">
        <div className="w-full max-w-[420px]">
          <div className="lg:hidden flex items-center justify-between mb-6">
            <Link
              to="/"
              className="inline-flex items-center gap-1.5 text-sm text-ink-500 dark:text-cream-400 hover:text-brand-600 font-bold transition"
            >
              <span>→</span>
              <span>خانه</span>
            </Link>
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-xl bg-brand-gradient flex items-center justify-center">
                <SiteImage
                  imageKey="icon_paw"
                  showPlaceholder={true}
                  placeholderContent={<span className="text-base">🐾</span>}
                  className="w-5 h-5 object-contain"
                />
              </div>
              <span className="font-miko text-lg text-ink-900 dark:text-cream-100">میکو</span>
            </div>
          </div>

          <div className="bg-paper-50 dark:bg-ink-800 rounded-3xl shadow-editorial border border-ink-200/60 dark:border-dark-700 overflow-hidden">
            <div className="px-6 pt-8 pb-6 text-center">
              <h1 className="font-display text-2xl font-black text-ink-900 dark:text-cream-100 mb-2">
                ورود به حساب
              </h1>
              <p className="text-[13px] text-ink-500 dark:text-cream-400">
                برای دسترسی به پنل، اطلاعات خود را وارد کنید.
              </p>
            </div>

            <div className="px-6 pb-8">
              {hasPendingCart && (
                <div className="mb-5 flex items-start gap-3 p-3 rounded-xl bg-accent-50 dark:bg-accent-500/10 border border-accent-200 dark:border-accent-500/20">
                  <SiteImage imageKey="icon_cart" fallback="🛒" alt="" className="text-lg" />
                  <div className="flex-1 min-w-0 text-[11px]">
                    <span className="font-bold text-accent-800 dark:text-accent-200">
                      سبد شما ({pendingCartCount} سفارش) در انتظار است.
                    </span>
                    {/* ✅ FIX v7: متن آپدیت شد — submit خودکار انجام نمی‌شه */}
                    <p className="text-accent-700 dark:text-accent-300 mt-0.5">
                      پس از ورود، می‌توانید سفارش را در سبد تکمیل کنید.
                    </p>
                  </div>
                </div>
              )}

              {hasPendingDog && !hasPendingOrder && (
                <div className="mb-5 flex items-start gap-3 p-3 rounded-xl bg-accent-50 dark:bg-accent-500/10 border border-accent-200 dark:border-accent-500/20">
                  <SiteImage imageKey="icon_dog" fallback="🐕" alt="" className="text-lg" />
                  <div className="flex-1 min-w-0 text-[11px]">
                    <span className="font-bold text-accent-800 dark:text-accent-200">
                      سگ «{pendingDogs[0].dog_name}» آمادهٔ افزودن است.
                    </span>
                    <p className="text-accent-700 dark:text-accent-300 mt-0.5">
                      بعد از ورود خودکار به پنل اضافه می‌شود.
                    </p>
                  </div>
                </div>
              )}

              {hasPendingOrder && !hasPendingCart && (
                <div className="mb-5 flex items-start gap-3 p-3 rounded-xl bg-brand-50 dark:bg-brand-500/10 border border-brand-200 dark:border-brand-500/20">
                  <SiteImage imageKey="icon_cart" fallback="🛒" alt="" className="text-lg" />
                  <div className="flex-1 min-w-0 text-[11px]">
                    <span className="font-bold text-brand-800 dark:text-brand-200">
                      سفارش شما در انتظار است.
                    </span>
                    <p className="text-brand-700 dark:text-brand-300 mt-0.5">
                      پس از ورود، به سبد خرید اضافه می‌شود تا بتوانید چند سگ را با هم پرداخت کنید.
                    </p>
                  </div>
                </div>
              )}

              {error && (
                <div className="mb-5 p-3 rounded-xl bg-rose-50 dark:bg-rose-500/10 border border-rose-200 dark:border-rose-500/20 text-[11px] text-rose-700 dark:text-rose-300 font-bold">
                  ⚠️ {error}
                </div>
              )}

              <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                  <label className="block text-xs font-bold text-ink-800 dark:text-cream-200 mb-1.5">
                    نام کاربری
                  </label>
                  <input
                    type="text"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    placeholder="نام کاربری خود را وارد کنید"
                    className={inputBase}
                    required
                    disabled={loading}
                    autoComplete="username"
                    autoFocus
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-ink-800 dark:text-cream-200 mb-1.5">
                    رمز عبور
                  </label>
                  <div className="relative">
                    <input
                      type={showPassword ? 'text' : 'password'}
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      placeholder="رمز عبور خود را وارد کنید"
                      className={`${inputBase} pl-11`}
                      required
                      disabled={loading}
                      autoComplete="current-password"
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="absolute left-1.5 top-1/2 -translate-y-1/2 w-8 h-8 flex items-center justify-center text-ink-400 hover:text-brand-600 rounded-lg transition text-sm"
                      aria-label={showPassword ? 'پنهان کردن رمز' : 'نمایش رمز'}
                      tabIndex={-1}
                    >
                      {showPassword ? '🙈' : '👁️'}
                    </button>
                  </div>
                </div>

                <div className="pt-2">
                  <button
                    type="submit"
                    disabled={!canSubmit}
                    className={`w-full h-12 rounded-xl text-sm font-black transition-all duration-300 flex items-center justify-center gap-2 ${
                      !canSubmit
                        ? 'bg-ink-100 dark:bg-ink-700 text-ink-400 dark:text-cream-500 cursor-not-allowed'
                        : 'bg-brand-gradient hover:opacity-95 active:opacity-90 text-white shadow-brand hover:shadow-brand-lg hover:-translate-y-0.5 active:translate-y-0'
                    }`}
                  >
                    {loading ? (
                      <>
                        <span className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                        <span>
                          {/* ✅ FIX v7: متن loading آپدیت شد */}
                          {hasPendingCart
                            ? 'در حال انتقال به سبد...'
                            : hasPendingOrder
                              ? 'در حال افزودن به سبد...'
                              : 'در حال ورود...'}
                        </span>
                      </>
                    ) : (
                      <span>ورود به حساب</span>
                    )}
                  </button>
                </div>
              </form>

              <div className="relative my-6">
                <div className="absolute inset-0 flex items-center">
                  <div className="w-full border-t border-ink-200 dark:border-dark-700" />
                </div>
                <div className="relative flex justify-center">
                  <span className="px-3 bg-paper-50 dark:bg-ink-800 text-xs text-ink-400 font-medium">
                    حساب جدید دارید؟
                  </span>
                </div>
              </div>

              <Link
                to={registerUrl}
                className="w-full h-12 rounded-xl border border-ink-200 dark:border-dark-600 text-ink-800 dark:text-cream-100 hover:bg-ink-50 dark:hover:bg-ink-700/50 text-sm font-bold transition flex items-center justify-center gap-2 group"
              >
                <span>ایجاد حساب کاربری جدید</span>
                <span className="group-hover:-translate-x-1 transition-transform">←</span>
              </Link>
            </div>
          </div>

          <div className="lg:hidden text-center mt-6 text-xs text-ink-400 dark:text-cream-500">
            © ۱۴۰۴ سیستم تغذیه اختصاصی سگ (میکو)
          </div>
        </div>
      </main>
    </div>
  );
}
